import { Children, type ComponentPropsWithRef, type ReactNode } from 'react';
import { cn } from '@/lib/utils';
import {
	LoginPageForm,
	type LoginPageFormIcons,
	type LoginPageFormLabels,
	type LoginPageFormMode,
	type LoginPageFormProps,
	type LoginPageFormValues,
} from './login-form';
import { type LoginPageSocialItem, LoginPageSocialLogin, type LoginPageSocialLoginProps } from './login-social';

export const LOGIN_PAGE_BEIAN_URL = 'https://beian.miit.gov.cn/';

export type LoginPageLinkProps = {
	text?: ReactNode;
	url?: string;
};

export type LoginPageFooterLinks = {
	beian?: LoginPageLinkProps;
	links?: readonly LoginPageLinkProps[];
	policy?: LoginPageLinkProps;
	terms?: LoginPageLinkProps;
};

export type LoginPageLayoutProps = Omit<ComponentPropsWithRef<'div'>, 'content'> & {
	content?: ReactNode;
	footer?: ReactNode;
	header?: ReactNode;
	hero?: ReactNode;
};

export type LoginPageHeaderLabels = {
	registerAction?: ReactNode;
	registerPrompt?: ReactNode;
};

export type LoginPageHeaderProps = Omit<ComponentPropsWithRef<'header'>, 'title'> & {
	actions?: ReactNode;
	headingId?: string;
	labels?: LoginPageHeaderLabels;
	logo?: ReactNode;
	onRegister?: () => void;
	subtitle?: ReactNode;
	title?: ReactNode;
};

export type LoginPageFooterProps = ComponentPropsWithRef<'footer'> &
	LoginPageFooterLinks & {
		copyright?: ReactNode;
		separator?: ReactNode;
	};

export type LoginPageHeroProps = ComponentPropsWithRef<'aside'>;

export type LoginPageCompositeProps = Omit<ComponentPropsWithRef<'div'>, 'content' | 'onSubmit' | 'title'> & {
	content?: ReactNode;
	defaultValues?: Partial<LoginPageFormValues>;
	disabled?: boolean;
	footer?: ReactNode;
	footerLinks?: LoginPageFooterLinks;
	form?: ReactNode;
	formIcons?: LoginPageFormIcons;
	formLabels?: LoginPageFormLabels;
	formMode?: LoginPageFormMode;
	header?: ReactNode;
	headerLabels?: LoginPageHeaderLabels;
	headingId?: string;
	hero?: ReactNode;
	logo?: ReactNode;
	onForgotPassword?: () => void;
	onRegister?: () => void;
	onSubmit?: LoginPageFormProps['onSubmit'];
	orgValue?: string;
	showOrg?: boolean;
	showPasswordToggle?: boolean;
	showRemember?: boolean;
	social?: ReactNode;
	socialColumns?: LoginPageSocialLoginProps['columns'];
	socialTitle?: ReactNode;
	socials?: readonly LoginPageSocialItem[];
	subtitle?: ReactNode;
	title?: ReactNode;
};

export function LoginPageComposite({
	children,
	className,
	content,
	defaultValues,
	disabled,
	footer,
	footerLinks,
	form,
	formIcons,
	formLabels,
	formMode,
	header,
	headerLabels,
	headingId,
	hero,
	logo,
	onForgotPassword,
	onRegister,
	onSubmit,
	orgValue,
	showOrg,
	showPasswordToggle,
	showRemember,
	social,
	socialColumns,
	socialTitle,
	socials,
	subtitle = '登录系统',
	title,
	...props
}: LoginPageCompositeProps) {
	const headerContent =
		header === undefined ? (
			<LoginPageHeader
				logo={logo}
				title={title}
				subtitle={subtitle}
				headingId={headingId}
				labels={headerLabels}
				onRegister={onRegister}
			/>
		) : (
			header
		);
	const formContent =
		form === undefined ? (
			<LoginPageForm
				onSubmit={onSubmit}
				defaultValues={defaultValues}
				showOrg={showOrg}
				orgValue={orgValue}
				onForgotPassword={onForgotPassword}
				mode={formMode}
				labels={formLabels}
				icons={formIcons}
				showRemember={showRemember}
				showPasswordToggle={showPasswordToggle}
				disabled={disabled}
			/>
		) : (
			form
		);
	const socialContent =
		social === undefined ? (
			<LoginPageSocialLogin socials={socials} title={socialTitle} columns={socialColumns} />
		) : (
			social
		);
	const contentNode =
		content === undefined ? (
			<>
				{formContent}
				{socialContent}
				{children}
			</>
		) : (
			content
		);
	const footerContent =
		footer === undefined ? (
			<LoginPageFooter
				policy={footerLinks?.policy}
				terms={footerLinks?.terms}
				beian={footerLinks?.beian}
				links={footerLinks?.links}
			/>
		) : (
			(footer ?? undefined)
		);

	return (
		<LoginPageLayout
			className={className}
			header={headerContent}
			content={contentNode}
			footer={footerContent}
			hero={hero}
			{...props}
		/>
	);
}

export function LoginPageLayout({
	header,
	children,
	content,
	hero,
	footer,
	className,
	...props
}: LoginPageLayoutProps) {
	return (
		<div data-slot='login-page' className={cn('bg-base-100 flex min-h-svh min-w-0', className)} {...props}>
			<div
				data-slot='login-page-panel'
				className={cn('flex min-w-0 flex-1 flex-col', hero && 'lg:w-[32rem] lg:flex-none xl:w-[36rem]')}
			>
				<div className='flex flex-1 items-center px-4 py-10 sm:px-8 lg:px-12 xl:px-16'>
					<div className='mx-auto w-full max-w-sm'>
						{header}
						{content}
						{children}
					</div>
				</div>
				{footer !== undefined ? (
					<div data-slot='login-page-footer-region' className='shrink-0 px-4 py-4 sm:px-8 lg:px-12 xl:px-16'>
						{footer}
					</div>
				) : null}
			</div>
			{hero ? <LoginPageHero>{hero}</LoginPageHero> : null}
		</div>
	);
}

export function LoginPageHeader({
	actions,
	headingId,
	labels,
	logo,
	onRegister,
	subtitle,
	title,
	className,
	...props
}: LoginPageHeaderProps) {
	return (
		<header data-slot='login-page-header' className={className} {...props}>
			<div className='flex min-w-0 items-center gap-3'>
				{logo ? <span className='grid size-10 shrink-0 place-items-center'>{logo}</span> : null}
				{title ? <div className='min-w-0 flex-1 truncate text-lg font-semibold'>{title}</div> : null}
				{actions}
			</div>
			{subtitle ? (
				<h1 id={headingId} className='mt-8 text-2xl leading-9 font-bold tracking-tight'>
					{subtitle}
				</h1>
			) : null}
			{onRegister ? (
				<p className='text-base-content/60 mt-2 text-sm leading-6'>
					{labels?.registerPrompt ?? '尚未加入？'}{' '}
					<button type='button' onClick={onRegister} className='text-primary hover:text-primary/80 font-semibold'>
						{labels?.registerAction ?? '现在注册'}
					</button>
				</p>
			) : null}
		</header>
	);
}

export function LoginPageFooter({
	beian,
	copyright,
	links,
	policy,
	separator = <span aria-hidden='true'>•</span>,
	terms,
	className,
	...props
}: LoginPageFooterProps) {
	const items: ReactNode[] = [copyright === undefined ? `© ${new Date().getFullYear()}` : copyright];
	const policyLink = renderLoginPageLink(policy, '隐私政策');
	const termsLink = renderLoginPageLink(terms, '服务条款');
	if (policyLink) items.push(policyLink);
	if (termsLink) items.push(termsLink);
	for (const link of links ?? []) {
		const item = renderLoginPageLink(link);
		if (item) items.push(item);
	}
	const beianLink = renderLoginPageLink(beian?.text ? { ...beian, url: beian.url ?? LOGIN_PAGE_BEIAN_URL } : undefined);
	if (beianLink) items.push(beianLink);
	const visibleItems = items.filter((item) => item !== null && item !== undefined && item !== false);
	const separatorNode = <span className='mx-1.5'>{separator}</span>;

	return (
		<footer
			data-slot='login-page-footer'
			className={cn('text-base-content/60 text-center text-xs leading-6', className)}
			{...props}
		>
			{Children.toArray(visibleItems.flatMap((item) => [separatorNode, item]).slice(1))}
		</footer>
	);
}

export function LoginPageHero({ className, ...props }: LoginPageHeroProps) {
	return (
		<aside
			data-slot='login-page-hero'
			className={cn('bg-neutral relative hidden min-w-0 flex-1 overflow-hidden lg:block', className)}
			{...props}
		/>
	);
}

export function getSafeLoginPageHref(url?: string) {
	if (!url) return undefined;
	const value = url.trim();
	if (!value || hasUnsafeLoginPageCharacter(value) || value.startsWith('//')) return undefined;
	if (
		value.startsWith('#') ||
		value.startsWith('/') ||
		value.startsWith('./') ||
		value.startsWith('../') ||
		value.startsWith('?')
	) {
		return value;
	}
	const scheme = /^([a-z][a-z\d+.-]*):/i.exec(value)?.[1]?.toLowerCase();
	if (!scheme) return value;
	if (scheme !== 'https') return undefined;
	try {
		const parsed = new URL(value);
		if (parsed.username || parsed.password) return undefined;
		return value;
	} catch {
		return undefined;
	}
}

function hasUnsafeLoginPageCharacter(value: string) {
	for (const character of value) {
		const code = character.charCodeAt(0);
		if (code <= 0x1f || code === 0x7f || character === '\\') return true;
	}
	return false;
}

function renderLoginPageLink(link?: LoginPageLinkProps, defaultText?: ReactNode) {
	const href = getSafeLoginPageHref(link?.url);
	const text = link?.text ?? defaultText;
	if (!href || !text) return null;
	const external = href.startsWith('https:');
	return (
		<a
			href={href}
			target={external ? '_blank' : undefined}
			rel={external ? 'noopener noreferrer' : undefined}
			className='hover:text-base-content hover:underline'
		>
			{text}
		</a>
	);
}

export const LoginPage = {
	Composite: LoginPageComposite,
	Footer: LoginPageFooter,
	Form: LoginPageForm,
	Header: LoginPageHeader,
	Hero: LoginPageHero,
	Layout: LoginPageLayout,
	SocialLogin: LoginPageSocialLogin,
} as const;

'use client';

import { Building2, Eye, EyeOff, LoaderCircle, LockKeyhole, Mail, UserRound } from 'lucide-react';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { useEffect, useId, useState } from 'react';
import {
	Controller,
	type FieldErrors,
	type Mode,
	type SubmitErrorHandler,
	type SubmitHandler,
	useForm,
} from 'react-hook-form';
import { cn } from '@/lib/utils';

export type LoginPageFormMode = 'username' | 'email';

export type LoginPageFormValues = {
	org?: string;
	username?: string;
	email?: string;
	password: string;
	remember: boolean;
};

export type LoginPageFormLabels = {
	org?: string;
	username?: string;
	email?: string;
	password?: string;
	remember?: string;
	forgotPassword?: string;
	submit?: string;
	submitting?: string;
	showPassword?: string;
	hidePassword?: string;
};

export type LoginPageFormIcons = {
	org?: ReactNode;
	username?: ReactNode;
	email?: ReactNode;
	password?: ReactNode;
	showPassword?: ReactNode;
	hidePassword?: ReactNode;
};

export type LoginPageFormSubmitState = {
	disabled: boolean;
	isSubmitting: boolean;
	isValid: boolean;
};

export type LoginPageFormProps = Omit<ComponentPropsWithRef<'form'>, 'defaultValue' | 'onSubmit'> & {
	actions?: ReactNode;
	afterFields?: ReactNode;
	beforeFields?: ReactNode;
	defaultValues?: Partial<LoginPageFormValues>;
	disabled?: boolean;
	icons?: LoginPageFormIcons;
	labels?: LoginPageFormLabels;
	mode?: LoginPageFormMode;
	onForgotPassword?: () => void;
	onInvalid?: SubmitErrorHandler<LoginPageFormValues>;
	onSubmit?: (values: LoginPageFormValues) => void | Promise<void>;
	orgValue?: string;
	renderSubmit?: (state: LoginPageFormSubmitState) => ReactNode;
	showOrg?: boolean;
	showPasswordToggle?: boolean;
	showRemember?: boolean;
	validationMode?: Mode;
};

export function LoginPageForm({
	actions,
	afterFields,
	beforeFields,
	className,
	defaultValues,
	disabled = false,
	icons,
	labels,
	mode = 'username',
	onForgotPassword,
	onInvalid,
	onSubmit,
	orgValue,
	renderSubmit,
	showOrg = false,
	showPasswordToggle = true,
	showRemember = true,
	validationMode = 'onChange',
	...props
}: LoginPageFormProps) {
	const id = useId();
	const [showPassword, setShowPassword] = useState(false);
	const {
		control,
		handleSubmit,
		register,
		setValue,
		formState: { errors, isSubmitting, isValid },
	} = useForm<LoginPageFormValues>({
		mode: validationMode,
		defaultValues: {
			remember: false,
			...defaultValues,
			...(orgValue !== undefined ? { org: orgValue } : {}),
		},
	});

	useEffect(() => {
		if (orgValue !== undefined) setValue('org', orgValue, { shouldValidate: true });
	}, [orgValue, setValue]);

	const text = {
		org: labels?.org ?? '组织',
		username: labels?.username ?? '用户名',
		email: labels?.email ?? 'Email',
		password: labels?.password ?? '密码',
		remember: labels?.remember ?? '记住登录',
		forgotPassword: labels?.forgotPassword ?? '忘记密码？',
		submit: labels?.submit ?? '登录',
		submitting: labels?.submitting ?? '登录中',
		showPassword: labels?.showPassword ?? '显示密码',
		hidePassword: labels?.hidePassword ?? '隐藏密码',
	};
	const submitState = {
		disabled: disabled || isSubmitting || (validationMode !== 'onSubmit' && !isValid),
		isSubmitting,
		isValid,
	};
	const submitValid: SubmitHandler<LoginPageFormValues> = (values) => onSubmit?.(values);

	return (
		<form
			{...props}
			noValidate
			className={cn('mt-8 space-y-5', className)}
			onSubmit={handleSubmit(submitValid, onInvalid)}
		>
			{beforeFields}
			<div className='space-y-4'>
				{showOrg ? (
					<LoginPageFormField
						id={`${id}-org`}
						label={text.org}
						icon={icons?.org ?? <Building2 className='size-4' />}
						error={errors.org}
					>
						<input
							id={`${id}-org`}
							autoComplete='organization'
							className='min-w-0 flex-1 bg-transparent outline-none'
							defaultValue={orgValue ?? defaultValues?.org}
							disabled={disabled}
							readOnly={orgValue !== undefined}
							required
							aria-invalid={Boolean(errors.org)}
							aria-describedby={errors.org ? `${id}-org-error` : undefined}
							{...register('org', { required: `${text.org}不能为空` })}
						/>
					</LoginPageFormField>
				) : null}

				{mode === 'email' ? (
					<LoginPageFormField
						id={`${id}-email`}
						label={text.email}
						icon={icons?.email ?? <Mail className='size-4' />}
						error={errors.email}
					>
						<input
							id={`${id}-email`}
							type='email'
							autoComplete='email'
							className='min-w-0 flex-1 bg-transparent outline-none'
							defaultValue={defaultValues?.email}
							disabled={disabled}
							required
							aria-invalid={Boolean(errors.email)}
							aria-describedby={errors.email ? `${id}-email-error` : undefined}
							{...register('email', {
								required: `${text.email}不能为空`,
								pattern: { value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, message: `${text.email}格式不正确` },
							})}
						/>
					</LoginPageFormField>
				) : (
					<LoginPageFormField
						id={`${id}-username`}
						label={text.username}
						icon={icons?.username ?? <UserRound className='size-4' />}
						error={errors.username}
					>
						<input
							id={`${id}-username`}
							autoComplete='username'
							className='min-w-0 flex-1 bg-transparent outline-none'
							defaultValue={defaultValues?.username}
							disabled={disabled}
							required
							aria-invalid={Boolean(errors.username)}
							aria-describedby={errors.username ? `${id}-username-error` : undefined}
							{...register('username', { required: `${text.username}不能为空` })}
						/>
					</LoginPageFormField>
				)}

				<LoginPageFormField
					id={`${id}-password`}
					label={text.password}
					icon={icons?.password ?? <LockKeyhole className='size-4' />}
					error={errors.password}
					actions={
						showPasswordToggle ? (
							<button
								type='button'
								aria-label={showPassword ? text.hidePassword : text.showPassword}
								title={showPassword ? text.hidePassword : text.showPassword}
								className='hover:bg-base-200 grid size-8 shrink-0 place-items-center rounded'
								disabled={disabled}
								onClick={() => setShowPassword((current) => !current)}
							>
								{showPassword
									? (icons?.hidePassword ?? <EyeOff className='size-4' />)
									: (icons?.showPassword ?? <Eye className='size-4' />)}
							</button>
						) : null
					}
				>
					<input
						id={`${id}-password`}
						type={showPassword ? 'text' : 'password'}
						autoComplete='current-password'
						className='min-w-0 flex-1 bg-transparent outline-none'
						defaultValue={defaultValues?.password}
						disabled={disabled}
						required
						aria-invalid={Boolean(errors.password)}
						aria-describedby={errors.password ? `${id}-password-error` : undefined}
						{...register('password', { required: `${text.password}不能为空` })}
					/>
				</LoginPageFormField>
			</div>
			{afterFields}

			{actions !== undefined ? (
				actions
			) : showRemember || onForgotPassword ? (
				<div className='flex min-h-8 flex-wrap items-center justify-between gap-3'>
					{showRemember ? (
						<Controller
							name='remember'
							control={control}
							render={({ field }) => (
								<label className='inline-flex cursor-pointer items-center gap-2 text-sm'>
									<input
										type='checkbox'
										name={field.name}
										ref={field.ref}
										checked={field.value === true}
										className='checkbox checkbox-sm'
										disabled={disabled}
										onBlur={field.onBlur}
										onChange={(event) => field.onChange(event.target.checked)}
									/>
									<span>{text.remember}</span>
								</label>
							)}
						/>
					) : (
						<span />
					)}
					{onForgotPassword ? (
						<button
							type='button'
							className='text-primary hover:text-primary/80 text-sm font-semibold'
							disabled={disabled}
							onClick={onForgotPassword}
						>
							{text.forgotPassword}
						</button>
					) : null}
				</div>
			) : null}

			{renderSubmit ? (
				renderSubmit(submitState)
			) : (
				<button
					type='submit'
					className='bg-primary text-primary-content inline-flex h-10 w-full items-center justify-center gap-2 rounded-md px-4 text-sm font-semibold shadow-sm disabled:cursor-not-allowed disabled:opacity-50'
					disabled={submitState.disabled}
				>
					{isSubmitting ? <LoaderCircle aria-hidden='true' className='size-4 animate-spin' /> : null}
					{isSubmitting ? text.submitting : text.submit}
				</button>
			)}
		</form>
	);
}

type LoginPageFormFieldProps = {
	actions?: ReactNode;
	children: ReactNode;
	error?: FieldErrors<LoginPageFormValues>[keyof LoginPageFormValues];
	icon?: ReactNode;
	id: string;
	label: ReactNode;
};

function LoginPageFormField({ actions, children, error, icon, id, label }: LoginPageFormFieldProps) {
	return (
		<div className='grid gap-1.5'>
			<label className='text-base-content/75 text-xs font-medium' htmlFor={id}>
				{label}
			</label>
			<div className='border-base-300 bg-base-100 focus-within:border-primary focus-within:ring-primary focus-within:ring-offset-base-100 flex min-h-10 items-center gap-2 rounded-md border px-2 focus-within:ring-2 focus-within:ring-offset-2'>
				{icon ? <span className='text-base-content/45 grid size-5 shrink-0 place-items-center'>{icon}</span> : null}
				{children}
				{actions}
			</div>
			{error?.message ? (
				<span id={`${id}-error`} role='alert' className='text-error text-xs'>
					{String(error.message)}
				</span>
			) : null}
		</div>
	);
}

import type { ComponentPropsWithRef, ReactNode } from 'react';
import { cn } from '@/lib/utils';

export type LoginPageSocialItem = {
	disabled?: boolean;
	icon?: ReactNode;
	id?: string;
	name: string;
	onClick: () => void;
};

export type LoginPageSocialLoginProps = Omit<ComponentPropsWithRef<'div'>, 'title'> & {
	columns?: 1 | 2 | 3;
	socials?: readonly LoginPageSocialItem[];
	title?: ReactNode;
};

export function LoginPageSocialLogin({
	columns = 2,
	socials,
	title = '其他登录方式',
	className,
	...props
}: LoginPageSocialLoginProps) {
	if (!socials?.length) return null;
	const columnsClass = {
		1: 'grid-cols-1',
		2: 'grid-cols-1 sm:grid-cols-2',
		3: 'grid-cols-1 sm:grid-cols-3',
	}[columns];

	return (
		<div data-slot='login-page-social' className={cn('mt-8', className)} {...props}>
			<div className='relative'>
				<div className='absolute inset-0 flex items-center' aria-hidden='true'>
					<div className='border-base-300 w-full border-t' />
				</div>
				<div className='relative flex justify-center text-xs font-medium'>
					<span className='bg-base-100 text-base-content/60 px-4'>{title}</span>
				</div>
			</div>
			<div className={cn('mt-5 grid gap-2', columnsClass)}>
				{socials.map((social) => (
					<button
						key={social.id ?? social.name}
						type='button'
						disabled={social.disabled}
						className='border-base-300 bg-base-100 hover:bg-base-200/70 inline-flex h-9 min-w-0 items-center justify-center gap-2 rounded-md border px-3 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50'
						onClick={social.onClick}
					>
						{social.icon ? <span className='grid size-4 shrink-0 place-items-center'>{social.icon}</span> : null}
						<span className='truncate'>{social.name}</span>
					</button>
				))}
			</div>
		</div>
	);
}

export * from './login-form';
export * from './login-page';
export * from './login-social';
